  readonly links: number;
  readonly rejected: number;
}

/** The run broke. One plain sentence, never a stack trace. */
export interface Failed {
  readonly event: "failed";
  readonly message: string;
}

export type StreamEvent =
  | GenerationStarted
  | ProposalAccepted
  | ProposalRejected
  | BeliefsPropagated
  | Verdict
  | Receipt
  | Done
  | Failed;
